document.addEventListener('DOMContentLoaded',async()=>{
 const body=document.getElementById('campaigns'),msg=document.getElementById('campaign-msg');
 const esc=v=>String(v??'');
 async function carregar(){try{const d=await apiFetch('/operacoes/admin/newsletter');const vals=document.querySelectorAll('.cartao-stat .valor-stat');if(vals[0])vals[0].textContent=d.total??0;if(vals[1])vals[1].textContent=d.totalRegistos??0;body.replaceChildren();if(!d.campanhas?.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=3;td.textContent='Ainda não existem campanhas.';tr.append(td);body.append(tr);return;}for(const c of d.campanhas){const tr=document.createElement('tr');for(const v of [c.assunto,c.enviada_em?new Date(c.enviada_em).toLocaleString('pt-PT'):(c.estado||'Rascunho'),`${Number(c.enviados||0)} enviados · ${Number(c.falhas||0)} falhas`]){const td=document.createElement('td');td.textContent=esc(v);tr.append(td)}if(c.estado==='rascunho'){const td=document.createElement('td'),btn=document.createElement('button');btn.type='button';btn.textContent='Enviar';btn.addEventListener('click',async()=>{if(!confirm('Enviar esta campanha a todos os subscritores ativos?'))return;btn.disabled=true;try{const r=await apiFetch(`/operacoes/admin/newsletter/campanhas/${c.id}/enviar`,{method:'POST',body:JSON.stringify({})});alert(`Campanha processada: ${r.enviados} enviados, ${r.falhas} falhas.`);await carregar()}catch(e){alert(e.message)}finally{btn.disabled=false}});td.append(btn);tr.append(td)}body.append(tr)}}catch(e){body.replaceChildren();const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=3;td.textContent=e.message||'Erro ao carregar.';tr.append(td);body.append(tr)}}
 document.getElementById('campaign-form').addEventListener('submit',async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('button[type="submit"]');btn.disabled=true;msg.textContent='A guardar…';try{await apiFetch('/operacoes/admin/newsletter/campanhas',{method:'POST',body:JSON.stringify({assunto:document.getElementById('campaign-subject').value,conteudo:document.getElementById('campaign-content').value})});msg.textContent='Rascunho guardado.';e.currentTarget.reset();await carregar()}catch(err){msg.textContent=err.message||'Não foi possível guardar.'}finally{btn.disabled=false}});
 await carregar();
});
